package tv.vela.launcher;

import android.app.*;import android.content.*;import android.graphics.Bitmap;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.*;

/** Shared production bindings and native remote editor, on the explicitly owned emulator only. */
public final class AndroidRemoteTest extends Instrumentation {
    public static final class Target extends Activity {public void onCreate(Bundle state){super.onCreate(state);setContentView(new TextView(this));}}
    private Context context;private Activity activity;private String previous,profile,phase="setup";private boolean lite;private ActivityMonitor monitor;private final Bundle result=new Bundle();
    interface Ready {boolean ready()throws Exception;}
    void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    Object field(Object o,String name)throws Exception{for(Class<?> type=o.getClass();type!=null;type=type.getSuperclass())try{Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException next){}throw new NoSuchFieldException(name);}
    void ui(Runnable work){Throwable[] failure={null};runOnMainSync(()->{try{work.run();}catch(Throwable e){failure[0]=e;}});waitForIdleSync();if(failure[0]!=null)throw new AssertionError(failure[0]);}
    void await(Ready ready)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){waitForIdleSync();if(ready.ready())return;Thread.sleep(40);}throw new AssertionError("Timeout: "+phase);}
    VelaHub hub()throws Exception{return (VelaHub)field(activity,"hub");}
    List<View> controls()throws Exception{return (List<View>)field(hub(),"controls");}
    void click(int index)throws Exception{View v=controls().get(index);ui(v::requestFocus);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();}
    void clickText(String label)throws Exception{for(View v:controls())if(v instanceof TextView&&((TextView)v).getText().toString().startsWith(L10n.text(label))){ui(v::requestFocus);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();return;}throw new AssertionError("Missing row: "+label);}
    KeyEvent event(long start,int action,int code,int repeat,int device,int scan,int flags){return new KeyEvent(start,SystemClock.uptimeMillis(),action,code,repeat,0,device,scan,flags);}
    void press(int code){long start=SystemClock.uptimeMillis();ui(()->activity.dispatchKeyEvent(event(start,0,code,0,0,0,0)));ui(()->activity.dispatchKeyEvent(event(start,1,code,0,0,0,0)));}
    void shot(String name)throws Exception{Thread.sleep(250);Bitmap b=getUiAutomation().takeScreenshot();check(b!=null&&b.getWidth()==3840,"Native 4K required");try(OutputStream out=new FileOutputStream(new File(context.getExternalFilesDir(null),"remote-"+(lite?"lite-":"full-")+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    void model()throws Exception{
        check(!VelaRemote.allowed(KeyEvent.KEYCODE_HOME)&&!VelaRemote.allowed(KeyEvent.KEYCODE_BACK)&&!VelaRemote.allowed(KeyEvent.KEYCODE_VOLUME_UP)&&!VelaRemote.allowed(KeyEvent.KEYCODE_DPAD_CENTER)&&!VelaRemote.allowed(KeyEvent.KEYCODE_BUTTON_A),"Reserved control can be remapped");
        check(VelaRemote.allowed(289),"Newer app buttons are excluded by the old 288-key limit");
        VelaRemote.assign(context,"voice_key",KeyEvent.KEYCODE_PROG_BLUE);check(VelaRemote.read(context).size()==1,"Legacy voice mapping lost");
        VelaRemote.set(context,KeyEvent.KEYCODE_PROG_RED,0,0,"widgets");VelaRemote.set(context,KeyEvent.KEYCODE_PROG_RED,0,1,"profiles");check(!VelaRemote.prefs(context).contains("voice_key")&&VelaRemote.voice(context,KeyEvent.KEYCODE_PROG_BLUE),"Legacy migration changed its action");
        JSONObject copy=VelaWorkspace.snapshot(context);check(copy.getJSONObject("settings").getJSONObject("vela-remote").has("bindings"),"Bindings omitted from portable backup");JSONObject read=VelaWorkspace.read(new ByteArrayInputStream(copy.toString().getBytes("UTF-8")));VelaRemote.prefs(context).edit().clear().commit();VelaWorkspace.apply(context,read,true);check(VelaRemote.read(context).size()==3,"Backup did not restore gestures");
        for(String action:new String[]{"https://example.invalid/secret","app:not a package","shell:reboot"}){boolean rejected=false;try{VelaRemote.validate(new JSONArray().put(new VelaRemote.Binding(KeyEvent.KEYCODE_PROG_GREEN,0,0,action).json()));}catch(JSONException good){rejected=true;}check(rejected,"Unsafe action accepted");}
        boolean duplicate=false;JSONObject b=new VelaRemote.Binding(KeyEvent.KEYCODE_PROG_GREEN,0,0,"apps").json();try{VelaRemote.validate(new JSONArray().put(b).put(b));}catch(JSONException good){duplicate=true;}check(duplicate,"Duplicate binding accepted");
        String other=VelaWorkspace.create(context,"Other · Demo");VelaWorkspace.select(context,other);check(VelaRemote.read(context).isEmpty(),"Profile inherited another remote map");VelaWorkspace.select(context,profile);VelaWorkspace.delete(context,other);
    }
    void gestures()throws Exception{
        VelaRemote.prefs(context).edit().clear().commit();VelaRemote.set(context,KeyEvent.KEYCODE_PROG_RED,0,0,"apps");VelaRemote.set(context,KeyEvent.KEYCODE_PROG_RED,0,1,"profiles");
        List<String> actions=new ArrayList<>();List<KeyEvent> replay=new ArrayList<>();VelaRemote.Dispatcher[] box={null};ui(()->box[0]=new VelaRemote.Dispatcher(activity,new VelaRemote.Dispatcher.Host(){public void activate(String action){actions.add(action);}public void replay(KeyEvent key){replay.add(key);}}));VelaRemote.Dispatcher d=box[0];
        long start=SystemClock.uptimeMillis();ui(()->{check(d.dispatch(event(start,0,KeyEvent.KEYCODE_PROG_RED,0,7,0,0)),"Down escaped");check(actions.isEmpty(),"Short action fired on down");d.dispatch(event(start,0,KeyEvent.KEYCODE_PROG_RED,2,7,0,0));d.dispatch(event(start,1,KeyEvent.KEYCODE_PROG_RED,0,7,0,0));});check(actions.equals(Collections.singletonList("apps")),"Repeat duplicated a short action");
        actions.clear();long held=SystemClock.uptimeMillis();ui(()->d.dispatch(event(held,0,KeyEvent.KEYCODE_PROG_RED,0,7,0,0)));Thread.sleep(VelaRemote.HOLD_MS+100);ui(()->{d.dispatch(event(held,0,KeyEvent.KEYCODE_PROG_RED,4,7,0,KeyEvent.FLAG_LONG_PRESS));d.dispatch(event(held,1,KeyEvent.KEYCODE_PROG_RED,0,7,0,0));});check(actions.equals(Collections.singletonList("profiles")),"Long press failed or also ran the short action");
        actions.clear();long canceled=SystemClock.uptimeMillis();ui(()->{d.dispatch(event(canceled,0,KeyEvent.KEYCODE_PROG_RED,0,7,0,0));d.dispatch(event(canceled,1,KeyEvent.KEYCODE_PROG_RED,0,7,0,KeyEvent.FLAG_CANCELED));});Thread.sleep(VelaRemote.HOLD_MS+60);check(actions.isEmpty(),"Canceled press ran an action");
        long paused=SystemClock.uptimeMillis();ui(()->{d.dispatch(event(paused,0,KeyEvent.KEYCODE_PROG_RED,0,7,0,0));d.cancel();});Thread.sleep(VelaRemote.HOLD_MS+60);check(actions.isEmpty()&&field(d,"down")==null,"Pause left a pending action");
        long interrupted=SystemClock.uptimeMillis();ui(()->{d.dispatch(event(interrupted,0,KeyEvent.KEYCODE_PROG_RED,0,7,0,0));check(!d.dispatch(event(interrupted,0,KeyEvent.KEYCODE_BACK,0,7,0,0)),"Back was intercepted");});Thread.sleep(VelaRemote.HOLD_MS+60);ui(()->check(d.dispatch(event(interrupted,1,KeyEvent.KEYCODE_PROG_RED,0,7,0,0)),"Interrupted key release escaped"));check(actions.isEmpty(),"A second button left the previous long press armed");
        VelaRemote.set(context,KeyEvent.KEYCODE_PROG_RED,0,0,"");long fallback=SystemClock.uptimeMillis();ui(()->{d.dispatch(event(fallback,0,KeyEvent.KEYCODE_PROG_RED,0,7,0,0));d.dispatch(event(fallback,1,KeyEvent.KEYCODE_PROG_RED,0,7,0,0));});check(actions.isEmpty()&&replay.size()==2&&replay.get(0).getAction()==0&&replay.get(1).getAction()==1,"Long-only binding swallowed the original short press");
        VelaRemote.set(context,0,537,0,"inputs");long scan=SystemClock.uptimeMillis();ui(()->{d.dispatch(event(scan,0,0,0,11,537,0));d.dispatch(event(scan,1,0,0,11,537,0));});check(actions.equals(Collections.singletonList("inputs")),"Unknown vendor scan code did not work");
        ui(()->{check(!d.dispatch(event(scan,0,0,0,11,538,0)),"Wrong vendor button matched");check(!d.dispatch(event(scan,0,KeyEvent.KEYCODE_DPAD_DOWN,0,7,0,0)),"Navigation was intercepted");d.cancel();});
        EditText[] edit={null};ui(()->{edit[0]=new EditText(activity);activity.addContentView(edit[0],new android.view.ViewGroup.LayoutParams(300,80));edit[0].requestFocus();check(!d.dispatch(event(scan,0,KeyEvent.KEYCODE_PROG_RED,0,7,0,0)),"Typing was intercepted");((android.view.ViewGroup)edit[0].getParent()).removeView(edit[0]);d.cancel();});
        VelaRemote.prefs(context).edit().clear().commit();
    }
    void editor()throws Exception{
        ui(()->((VelaHub.Owner)activity).tools(VelaHub.REMOTE));await(()->hub()!=null&&hub().page()==VelaHub.REMOTE);shot("list-empty");clickText("Add a button");check(hub().testingRemote(),"Learning mode was not entered");press(KeyEvent.KEYCODE_PROG_RED);check(!hub().testingRemote(),"Learned button stayed in capture mode");check(controls().get(0).hasFocus(),"Learning a button left focus outside the editor");shot("button");click(0);clickText("Home widgets");check(VelaRemote.find(VelaRemote.read(context),KeyEvent.KEYCODE_PROG_RED,0,0).action.equals("widgets"),"Editor did not save short action");click(1);clickText("Profiles");shot("button-assigned");
        clickText("Back");shot("list");clickText("Add a button");View cancel=controls().get(0);ui(cancel::requestFocus);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();check(!hub().testingRemote(),"The remote cannot click Cancel during learning");
        clickText("Add a button");press(KeyEvent.KEYCODE_BACK);check(!hub().testingRemote()&&hub().page()==VelaHub.REMOTE,"Back closed the entire settings page during learning");
        ui(()->hubQuiet().close());press(KeyEvent.KEYCODE_PROG_RED);await(()->hub()!=null&&hub().page()==VelaHub.WIDGETS);ui(()->hubQuiet().close());
        long held=SystemClock.uptimeMillis();ui(()->activity.dispatchKeyEvent(event(held,0,KeyEvent.KEYCODE_PROG_RED,0,0,0,0)));Thread.sleep(VelaRemote.HOLD_MS+80);ui(()->activity.dispatchKeyEvent(event(held,1,KeyEvent.KEYCODE_PROG_RED,0,0,0,0)));await(()->hub()!=null&&hub().page()==4);ui(()->hubQuiet().close());
        VelaRemote.set(context,KeyEvent.KEYCODE_PROG_GREEN,0,0,"app:"+getContext().getPackageName());monitor=addMonitor(Target.class.getName(),new ActivityResult(Activity.RESULT_CANCELED,null),true);press(KeyEvent.KEYCODE_PROG_GREEN);check(monitor.getHits()==1,"Production shortcut did not launch the selected app");removeMonitor(monitor);monitor=null;
        ui(()->((VelaHub.Owner)activity).tools(VelaHub.REMOTE));clickText("Add a button");press(KeyEvent.KEYCODE_PROG_GREEN);click(0);clickText("Open an app");await(()->controls().size()>1);boolean target=false;for(View v:controls())if(v instanceof TextView&&((TextView)v).getText().toString().contains("Remote test target"))target=true;check(target,"Installed app chooser omitted a launchable application");shot("apps");press(KeyEvent.KEYCODE_BACK);press(KeyEvent.KEYCODE_BACK);clickText("Remove this button");check(VelaRemote.find(VelaRemote.read(context),KeyEvent.KEYCODE_PROG_GREEN,0,0)==null,"Removing a shortcut left its mapping active");
        clickText("Reset shortcuts");clickText("Cancel");check(!VelaRemote.read(context).isEmpty(),"Reset cancellation changed bindings");shot("list-final");ui(()->hubQuiet().close());
        if(lite){VelaWorkspace.prefs(context,"lite_home").edit().putInt("start_section",2).commit();VelaRemote.set(context,KeyEvent.KEYCODE_PROG_GREEN,0,0,"home");press(KeyEvent.KEYCODE_PROG_GREEN);check(((Integer)field(activity,"section"))==2,"Home shortcut ignored the Lite start section");}
        else{VelaRemote.set(context,KeyEvent.KEYCODE_PROG_GREEN,0,0,"apps");press(KeyEvent.KEYCODE_PROG_GREEN);Object home=field(activity,"home");check(field(home,"panels")!=null,"Apps shortcut did not open the drawer");VelaRemote.set(context,KeyEvent.KEYCODE_PROG_GREEN,0,0,"home");press(KeyEvent.KEYCODE_PROG_GREEN);check(field(home,"panels")==null&&((View)field(home,"overlay")).getVisibility()==View.GONE&&((Integer)field(home,"filter"))==0,"Home shortcut left the app drawer open");}
    }
    VelaHub hubQuiet(){try{return hub();}catch(Exception e){throw new IllegalStateException(e);}}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){context=getTargetContext();lite=context.getPackageName().endsWith(".lite");try{
        try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("getprop ro.kernel.qemu");InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){check(in.read()=='1',"Owned emulator required");}
        RefinementHttp.install(url->null);previous=VelaWorkspace.active(context);if(Arrays.asList("Remote · Demo","Other · Demo").contains(VelaWorkspace.profiles(context).get(previous)))previous=VelaWorkspace.DEFAULT;for(Map.Entry<String,String> entry:VelaWorkspace.profiles(context).entrySet())if(Arrays.asList("Remote · Demo","Other · Demo").contains(entry.getValue())){VelaWorkspace.select(context,VelaWorkspace.DEFAULT);VelaWorkspace.delete(context,entry.getKey());}VelaWorkspace.select(context,previous);profile=VelaWorkspace.create(context,"Remote · Demo");VelaWorkspace.select(context,profile);L10n.choose(context,"es");Ui.init(context);VelaWidgets.State widgets=VelaWidgets.read(context);widgets.items.clear();widgets.items.add("clock");VelaWidgets.save(context,widgets);
        model();activity=startActivitySync(new Intent().setClassName(context,"tv.vela.launcher."+(lite?"LiteHomeActivity":"HomeActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();phase="gestures";gestures();phase="native-editor";editor();result.putString("result","PASS "+(lite?"Lite":"Full")+" remote learn, short/long, app launch, scan codes, repeat/cancel, native fallback, profiles and portable backup");
    }catch(Throwable failure){result.putString("result","FAIL "+phase+": "+failure);try{shot("failure");}catch(Exception ignored){}android.util.Log.e("VelaRemoteTest",phase,failure);}finally{if(monitor!=null)removeMonitor(monitor);if(activity!=null)ui(()->{try{Object d=field(activity,"remote");if(d!=null)((VelaRemote.Dispatcher)d).cancel();activity.finish();}catch(Exception ignored){}});if(previous!=null&&profile!=null)try{VelaWorkspace.select(context,previous);VelaWorkspace.delete(context,profile);}catch(Exception ignored){}}
        finish(result.getString("result","").startsWith("PASS")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
